-- 20261004000000: initial Manhaj schema (generated by scripts/generate_migration.py).
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;

CREATE TABLE dataset_manifests (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE diagnoses (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE duplicate_runs (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE embeddings (
	id VARCHAR NOT NULL, 
	record_id VARCHAR NOT NULL, 
	record_version INTEGER NOT NULL, 
	field VARCHAR NOT NULL, 
	model VARCHAR NOT NULL, 
	content_hash VARCHAR NOT NULL, 
	values JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE evaluation_runs (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE extraction_runs (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE phase_gates (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE record_versions (
	id VARCHAR NOT NULL, 
	record_id VARCHAR NOT NULL, 
	version INTEGER NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (record_id, version)
);

CREATE TABLE reviewers (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE source_items (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE sources (
	id VARCHAR NOT NULL, 
	sha256 VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (sha256)
);

CREATE TABLE training_exports (
	id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE methodology_rules (
	id VARCHAR NOT NULL, 
	source_id VARCHAR, 
	status VARCHAR NOT NULL, 
	version INTEGER NOT NULL, 
	phase INTEGER NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id)
);

CREATE TABLE objection_families (
	id VARCHAR NOT NULL, 
	source_id VARCHAR, 
	status VARCHAR NOT NULL, 
	version INTEGER NOT NULL, 
	phase INTEGER NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id)
);

CREATE TABLE objections (
	id VARCHAR NOT NULL, 
	source_id VARCHAR, 
	status VARCHAR NOT NULL, 
	version INTEGER NOT NULL, 
	phase INTEGER NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id)
);

CREATE TABLE reviews (
	id VARCHAR NOT NULL, 
	record_id VARCHAR NOT NULL, 
	reviewer_id VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reviewer_id) REFERENCES reviewers (id)
);

CREATE TABLE source_chunks (
	id VARCHAR NOT NULL, 
	source_id VARCHAR NOT NULL, 
	page_number INTEGER, 
	section VARCHAR NOT NULL, 
	text VARCHAR NOT NULL, 
	raw_text VARCHAR NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id)
);

CREATE TABLE objection_claims (
	id VARCHAR NOT NULL, 
	objection_id VARCHAR NOT NULL, 
	text VARCHAR NOT NULL, 
	claim_type VARCHAR NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(objection_id) REFERENCES objections (id)
);

CREATE TABLE objection_family_members (
	family_id VARCHAR NOT NULL, 
	objection_id VARCHAR NOT NULL, 
	PRIMARY KEY (family_id, objection_id), 
	FOREIGN KEY(family_id) REFERENCES objection_families (id), 
	FOREIGN KEY(objection_id) REFERENCES objections (id)
);

CREATE TABLE semantic_vectors (
    id TEXT PRIMARY KEY REFERENCES embeddings(id) ON DELETE CASCADE,
    record_id TEXT NOT NULL,
    record_version INTEGER NOT NULL,
    model TEXT NOT NULL,
    embedding extensions.vector(768) NOT NULL
);
CREATE INDEX semantic_vectors_hnsw ON semantic_vectors USING hnsw (embedding extensions.vector_cosine_ops);
CREATE INDEX source_chunks_source_page ON source_chunks(source_id, page_number);
CREATE INDEX reviews_record ON reviews(record_id);
CREATE INDEX record_versions_lookup ON record_versions(record_id, version);
CREATE INDEX embeddings_current ON embeddings(record_id, record_version, model);
CREATE FUNCTION manhaj_immutable_audit() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN RAISE EXCEPTION 'Audit history is append-only'; END; $$;
CREATE TRIGGER reviews_immutable BEFORE UPDATE OR DELETE ON reviews FOR EACH ROW EXECUTE FUNCTION manhaj_immutable_audit();
CREATE TRIGGER versions_immutable BEFORE UPDATE OR DELETE ON record_versions FOR EACH ROW EXECUTE FUNCTION manhaj_immutable_audit();
ALTER TABLE objections ADD CONSTRAINT objections_status CHECK (status IN ('draft','needs_review','approved','rejected'));
ALTER TABLE objections ADD CONSTRAINT objections_phase CHECK (phase IN (1,2));
ALTER TABLE objections ADD CONSTRAINT objections_version CHECK (version >= 1);
ALTER TABLE objections ADD CONSTRAINT objections_payload_status CHECK (payload->>'review_status' = status);
CREATE INDEX objections_status_phase ON objections(status,phase);
CREATE INDEX objections_keywords ON objections USING gin(to_tsvector('simple', coalesce(payload->>'normalized_objection_ar','') || ' ' || coalesce(payload->>'methodology_rule_ar','')));
