ALTER TABLE methodology_rules ADD CONSTRAINT methodology_rules_phase CHECK (phase IN (1,2));
ALTER TABLE methodology_rules ADD CONSTRAINT methodology_rules_version CHECK (version >= 1);
ALTER TABLE methodology_rules ADD CONSTRAINT methodology_rules_payload_status CHECK (payload->>'review_status' = status);
CREATE INDEX methodology_rules_status_phase ON methodology_rules(status,phase);
CREATE INDEX methodology_rules_keywords ON methodology_rules USING gin(to_tsvector('simple', coalesce(payload->>'normalized_objection_ar','') || ' ' || coalesce(payload->>'methodology_rule_ar','')));
ALTER TABLE objection_families ADD CONSTRAINT objection_families_status CHECK (status IN ('draft','needs_review','approved','rejected'));
ALTER TABLE objection_families ADD CONSTRAINT objection_families_phase CHECK (phase IN (1,2));
ALTER TABLE objection_families ADD CONSTRAINT objection_families_version CHECK (version >= 1);
ALTER TABLE objection_families ADD CONSTRAINT objection_families_payload_status CHECK (payload->>'review_status' = status);
CREATE INDEX objection_families_status_phase ON objection_families(status,phase);
CREATE INDEX objection_families_keywords ON objection_families USING gin(to_tsvector('simple', coalesce(payload->>'normalized_objection_ar','') || ' ' || coalesce(payload->>'methodology_rule_ar','')));
